export default {"files":{"10":{"file":"10_payments.md","fileNo":"10","doc_id":"NC-POL-10","title":"Payments","version":"2.0","effective_date":"2026-05-01","scope":"general"},"11":{"file":"11_cod_and_failed_payments.md","fileNo":"11","doc_id":"NC-POL-11","title":"Cash on Delivery and Failed Payments","version":"2.0","effective_date":"2026-05-01","scope":"general"},"12":{"file":"12_promo_code_rules.md","fileNo":"12","doc_id":"NC-POL-12","title":"Promo Code Rules","version":"2.0","effective_date":"2026-06-01","scope":"general"},"13":{"file":"13_sales_and_bundles.md","fileNo":"13","doc_id":"NC-POL-13","title":"Sales and Bundle Deals","version":"2.0","effective_date":"2026-06-01","scope":"specific"},"14":{"file":"14_store_credit.md","fileNo":"14","doc_id":"NC-POL-14","title":"Store Credit","version":"2.0","effective_date":"2026-03-01","scope":"general"},"15":{"file":"15_privacy_policy.md","fileNo":"15","doc_id":"NC-POL-15","title":"Privacy Policy","version":"2.0","effective_date":"2026-01-01","scope":"general"},"16":{"file":"16_data_requests_and_retention.md","fileNo":"16","doc_id":"NC-POL-16","title":"Data Requests and Retention","version":"2.0","effective_date":"2026-01-01","scope":"general"},"17":{"file":"17_seller_marketplace_rules.md","fileNo":"17","doc_id":"NC-POL-17","title":"Seller Marketplace Rules","version":"2.0","effective_date":"2026-02-01","scope":"specific"},"18":{"file":"18_seller_return_obligations.md","fileNo":"18","doc_id":"NC-POL-18","title":"Seller Return Obligations","version":"2.0","effective_date":"2026-04-01","scope":"specific"},"19":{"file":"19_remote_areas_addendum.md","fileNo":"19","doc_id":"NC-POL-19","title":"Remote Areas Addendum","version":"2.0","effective_date":"2026-04-01","scope":"regional"},"20":{"file":"20_international_addendum.md","fileNo":"20","doc_id":"NC-POL-20","title":"International Orders Addendum","version":"2.0","effective_date":"2026-04-01","scope":"regional"},"21":{"file":"21_shipping_fee_update_2027.md","fileNo":"21","doc_id":"NC-POL-21","title":"Shipping Fee Update 2027","version":"1.0","effective_date":"2027-02-01","scope":"general"},"00":{"file":"00_how_policies_work_together.md","fileNo":"00","doc_id":"NC-POL-00","title":"How NovaCart Policies Work Together","version":"1.0","effective_date":"2026-01-01","scope":"general"},"01":{"file":"01_returns_policy.md","fileNo":"01","doc_id":"NC-POL-01","title":"Returns Policy","version":"3.0","effective_date":"2026-03-01","scope":"general"},"02":{"file":"02_returns_policy_2025.md","fileNo":"02","doc_id":"NC-POL-02","title":"Returns Policy (Version 2)","version":"2.0","effective_date":"2025-06-01","scope":"general"},"03":{"file":"03_refunds_policy.md","fileNo":"03","doc_id":"NC-POL-03","title":"Refunds Policy","version":"2.0","effective_date":"2026-03-01","scope":"general"},"04":{"file":"04_non_returnable_items.md","fileNo":"04","doc_id":"NC-POL-04","title":"Non-Returnable Items","version":"2.0","effective_date":"2026-03-01","scope":"general"},"05":{"file":"05_shipping_policy.md","fileNo":"05","doc_id":"NC-POL-05","title":"Shipping Policy","version":"2.0","effective_date":"2026-01-15","scope":"general"},"06":{"file":"06_shipping_fees_and_free_shipping.md","fileNo":"06","doc_id":"NC-POL-06","title":"Shipping Fees and Free Shipping","version":"2.0","effective_date":"2026-01-15","scope":"general"},"07":{"file":"07_lost_or_damaged_deliveries.md","fileNo":"07","doc_id":"NC-POL-07","title":"Lost, Damaged and Wrong Deliveries","version":"2.0","effective_date":"2026-01-15","scope":"general"},"08":{"file":"08_warranty_policy.md","fileNo":"08","doc_id":"NC-POL-08","title":"Warranty Policy","version":"2.0","effective_date":"2026-01-15","scope":"general"},"09":{"file":"09_warranty_claims.md","fileNo":"09","doc_id":"NC-POL-09","title":"How to Make a Warranty Claim","version":"2.0","effective_date":"2026-01-15","scope":"general"}},"items":[{"id":"00:1.1","fileNo":"00","file":"00_how_policies_work_together.md","item":"1.1","heading":"1. Conventions","text":"Currency. All amounts are in Pakistani Rupees (PKR), written \"Rs.\". Amounts are whole rupees.","refs":[]},{"id":"00:1.2","fileNo":"00","file":"00_how_policies_work_together.md","item":"1.2","heading":"1. Conventions","text":"Tax. Listed prices include 18% GST. The GST contained in a GST-inclusive price is the price multiplied by 18 and divided by 118, rounded half up. GST is not shown separately unless a file says so.","refs":[]},{"id":"00:1.3","fileNo":"00","file":"00_how_policies_work_together.md","item":"1.3","heading":"1. Conventions","text":"Rounding. When a rule produces an amount that is not a whole rupee (a percentage discount, a restocking fee, a proportional share), the amount is rounded half up to the nearest whole rupee at the moment it is computed. Decimals are never carried into a later step.","refs":[]},{"id":"00:1.4","fileNo":"00","file":"00_how_policies_work_together.md","item":"1.4","heading":"1. Conventions","text":"Dates. Dates are written YYYY-MM-DD.","refs":[]},{"id":"00:1.5","fileNo":"00","file":"00_how_policies_work_together.md","item":"1.5","heading":"1. Conventions","text":"Business days. Business days are Monday to Friday. Public holidays are not excluded. Counting starts on the first business day after the event.","refs":[]},{"id":"00:1.6","fileNo":"00","file":"00_how_policies_work_together.md","item":"1.6","heading":"1. Conventions","text":"Days from delivery. A time limit of N days from delivery ends on the delivery date plus N calendar days. A request made on that last day is in time.","refs":[]},{"id":"00:1.7","fileNo":"00","file":"00_how_policies_work_together.md","item":"1.7","heading":"1. Conventions","text":"Full months. Full months elapsed from date A to date B are counted in whole calendar months. A month is complete on the same day of the month as date A. If the later month has no such day, it is complete on the last day of that month. Example: from 2026-01-10 to 2026-04-09 is 2 full months, and from 2026-01-10 to 2026-04-10 is 3 full months.","refs":[]},{"id":"00:1.8","fileNo":"00","file":"00_how_policies_work_together.md","item":"1.8","heading":"1. Conventions","text":"Contact date. The contact date is the day the customer asks a question or submits a request.","refs":[]},{"id":"00:2.1","fileNo":"00","file":"00_how_policies_work_together.md","item":"2.1","heading":"2. Regions, categories and sellers","text":"Metro cities are Islamabad, Lahore and Karachi. Only these three cities are Metro cities.","refs":[]},{"id":"00:2.2","fileNo":"00","file":"00_how_policies_work_together.md","item":"2.2","heading":"2. Regions, categories and sellers","text":"Remote areas are Azad Jammu & Kashmir and Gilgit-Baltistan.","refs":[]},{"id":"00:2.3","fileNo":"00","file":"00_how_policies_work_together.md","item":"2.3","heading":"2. Regions, categories and sellers","text":"International means delivery to the USA, the UK or the UAE. No other country is served.","refs":[]},{"id":"00:2.4","fileNo":"00","file":"00_how_policies_work_together.md","item":"2.4","heading":"2. Regions, categories and sellers","text":"Rest of Pakistan means every place in Pakistan that is not a Metro city and not a Remote area.","refs":[]},{"id":"00:2.5","fileNo":"00","file":"00_how_policies_work_together.md","item":"2.5","heading":"2. Regions, categories and sellers","text":"Every item belongs to exactly one category: electronics, clothing, grocery/perishables, furniture/bulky, or personal care. A bulky item is any item in the furniture/bulky category.","refs":[]},{"id":"00:2.6","fileNo":"00","file":"00_how_policies_work_together.md","item":"2.6","heading":"2. Regions, categories and sellers","text":"Items are either \"Sold by NovaCart\" or sold by a marketplace seller (see [file 17, Section 1]). Files that do not mention marketplace items apply to items Sold by NovaCart only.","refs":[{"fileNo":"17","section":"1"}]},{"id":"00:3.1","fileNo":"00","file":"00_how_policies_work_together.md","item":"3.1","heading":"3. Which version of a policy is in force","text":"Every file has an effective_date in its front matter. A file is in force on a contact date if its effective_date is on or before that date. A file whose effective_date is after the contact date is not yet in force and is not applied.","refs":[]},{"id":"00:3.2","fileNo":"00","file":"00_how_policies_work_together.md","item":"3.2","heading":"3. Which version of a policy is in force","text":"The contact date decides which file applies. The only exception is the validity of a promo code, which depends on the order date (see [file 12, Section 1]).","refs":[{"fileNo":"12","section":"1"}]},{"id":"00:4.1","fileNo":"00","file":"00_how_policies_work_together.md","item":"4.1","heading":"4. When two files disagree","text":"A file with scope \"regional\" overrides files with scope \"general\" or \"specific\" for the region it covers and for the topics it covers, whatever the dates. Topics a regional file does not mention follow the other files.","refs":[]},{"id":"00:4.2","fileNo":"00","file":"00_how_policies_work_together.md","item":"4.2","heading":"4. When two files disagree","text":"If two files in force cover the same topic with the same scope and have different effective dates, the file with the later effective_date applies. The customer must be told that the files differ and which one was used.","refs":[]},{"id":"00:4.3","fileNo":"00","file":"00_how_policies_work_together.md","item":"4.3","heading":"4. When two files disagree","text":"If two files in force have the same effective_date and different scope values, the file with the more specific scope applies. From least to most specific the order is: general, specific, regional.","refs":[]},{"id":"00:4.4","fileNo":"00","file":"00_how_policies_work_together.md","item":"4.4","heading":"4. When two files disagree","text":"If two files in force have the same effective_date, the same scope and different rules for the same topic, the files do not settle the question. The customer must be told what each file says and that NovaCart support must confirm.","refs":[]},{"id":"00:4.5","fileNo":"00","file":"00_how_policies_work_together.md","item":"4.5","heading":"4. When two files disagree","text":"Dates and scope are read only from the front matter of each file.","refs":[]},{"id":"00:5.1","fileNo":"00","file":"00_how_policies_work_together.md","item":"5.1","heading":"5. Order of calculation for checkout totals","text":"Totals are worked out in this order:\n\n1. Item prices: the sale price where an item is on sale, or the bundle price for a bundle (see [file 13, Section 1]).\n2. Merchandise subtotal: the sum of the item prices.\n3. Discount code: calculated on the eligible subtotal (see [file 12, Section 3]).\n4. Subtotal after discount: the merchandise subtotal minus the discount.\n5. Standard shipping fee: decided using the subtotal after discount (see [file 06, Section 2]).\n6. Extra charges: express fee, bulky surcharges and the COD fee. These are never discounted and never count toward free-shipping thresholds.\n7. Total payable: the subtotal after discount plus the shipping fee plus the extra charges.","refs":[{"fileNo":"13","section":"1"},{"fileNo":"12","section":"3"},{"fileNo":"06","section":"2"}]},{"id":"00:5.2","fileNo":"00","file":"00_how_policies_work_together.md","item":"5.2","heading":"5. Order of calculation for checkout totals","text":"The FREESHIP code works at step 5 (see [file 12, Section 5]).","refs":[{"fileNo":"12","section":"5"}]},{"id":"00:5.3","fileNo":"00","file":"00_how_policies_work_together.md","item":"5.3","heading":"5. Order of calculation for checkout totals","text":"Refunds are worked out under [file 01, Section 5] and [file 03].","refs":[{"fileNo":"01","section":"5"},{"fileNo":"03","section":null}]},{"id":"00:6.1","fileNo":"00","file":"00_how_policies_work_together.md","item":"6.1","heading":"6. How the policy files are organised","text":"Each file is named NN_topic.md. The number NN is also the last part of the doc_id (NC-POL-NN).","refs":[]},{"id":"00:6.2","fileNo":"00","file":"00_how_policies_work_together.md","item":"6.2","heading":"6. How the policy files are organised","text":"Each file starts with front matter holding doc_id, title, version, effective_date, last_updated and scope.","refs":[]},{"id":"00:6.3","fileNo":"00","file":"00_how_policies_work_together.md","item":"6.3","heading":"6. How the policy files are organised","text":"Rules are numbered by section and item. Section 3.2 of a file means item 3.2 under heading 3. Answers should cite the file name and the item number.","refs":[]},{"id":"00:6.4","fileNo":"00","file":"00_how_policies_work_together.md","item":"6.4","heading":"6. How the policy files are organised","text":"Cross-references are written as [file NN, Section X].","refs":[]},{"id":"01:1.1","fileNo":"01","file":"01_returns_policy.md","item":"1.1","heading":"1. Who this policy covers","text":"This policy covers items marked \"Sold by NovaCart\". Items sold by marketplace sellers follow the same windows and have extra rules in [file 18, Section 1].","refs":[{"fileNo":"18","section":"1"}]},{"id":"01:1.2","fileNo":"01","file":"01_returns_policy.md","item":"1.2","heading":"1. Who this policy covers","text":"To return an item, the customer opens My Orders, selects \"Return item\" and submits the request inside the return window in Section 2. NovaCart approves or declines the request within 1 business day.","refs":[]},{"id":"01:1.3","fileNo":"01","file":"01_returns_policy.md","item":"1.3","heading":"1. Who this policy covers","text":"An approved return must be handed to the courier within 5 days of approval. If it is not, the approval lapses and a new request is needed. The return window still applies to the new request.","refs":[]},{"id":"01:1.4","fileNo":"01","file":"01_returns_policy.md","item":"1.4","heading":"1. Who this policy covers","text":"NovaCart error means one of the following: the wrong item was delivered, the item is defective, or the item was damaged in transit, reported within the limits in [file 07, Section 1]. Every other return is a change-of-mind return.","refs":[{"fileNo":"07","section":"1"}]},{"id":"01:2.1","fileNo":"01","file":"01_returns_policy.md","item":"2.1","heading":"2. Return windows","text":"Return windows count from the delivery date (see [file 00, Section 1]).\n\n| Category | Return window |\n| --- | --- |\n| Electronics | 7 days |\n| Clothing | 30 days |\n| Furniture/bulky | 14 days |\n| Personal care | 14 days, sealed items only |\n| Grocery/perishables | Not returnable for change of mind (see [file 04, Section 1]) |","refs":[{"fileNo":"00","section":"1"},{"fileNo":"04","section":"1"}]},{"id":"01:2.2","fileNo":"01","file":"01_returns_policy.md","item":"2.2","heading":"2. Return windows","text":"Remote areas and International orders have their own return windows (see [file 19, Section 4] and [file 20, Section 6]).","refs":[{"fileNo":"19","section":"4"},{"fileNo":"20","section":"6"}]},{"id":"01:2.3","fileNo":"01","file":"01_returns_policy.md","item":"2.3","heading":"2. Return windows","text":"When the window has passed, change-of-mind returns are not accepted. A defective electronics or furniture item can still be handled under warranty (see [file 08, Section 4]).","refs":[{"fileNo":"08","section":"4"}]},{"id":"01:2.4","fileNo":"01","file":"01_returns_policy.md","item":"2.4","heading":"2. Return windows","text":"Items that cannot be returned for change of mind are listed in [file 04, Section 1].","refs":[{"fileNo":"04","section":"1"}]},{"id":"01:3.1","fileNo":"01","file":"01_returns_policy.md","item":"3.1","heading":"3. Condition of returned items","text":"Electronics must come back in the original packaging with all accessories. If an electronics item has been opened and is not defective, a restocking fee of 15% of the paid price applies. A sealed electronics item has no restocking fee.","refs":[]},{"id":"01:3.2","fileNo":"01","file":"01_returns_policy.md","item":"3.2","heading":"3. Condition of returned items","text":"Clothing must be unworn and unwashed with the tags attached. There is no restocking fee for clothing.","refs":[]},{"id":"01:3.3","fileNo":"01","file":"01_returns_policy.md","item":"3.3","heading":"3. Condition of returned items","text":"Furniture/bulky items must be unused and in the original packaging. A restocking fee of 10% of the paid price applies to non-defective furniture/bulky items.","refs":[]},{"id":"01:3.4","fileNo":"01","file":"01_returns_policy.md","item":"3.4","heading":"3. Condition of returned items","text":"Personal care items must be sealed and unopened. There is no restocking fee for personal care.","refs":[]},{"id":"01:3.5","fileNo":"01","file":"01_returns_policy.md","item":"3.5","heading":"3. Condition of returned items","text":"No restocking fee is charged on a NovaCart error return.","refs":[]},{"id":"01:4.1","fileNo":"01","file":"01_returns_policy.md","item":"4.1","heading":"4. Return fees","text":"One return fee is charged per return request, not per item. If the request includes any furniture/bulky item, the fee is the pickup fee of Rs. 2,000. Otherwise the fee is the return label fee of Rs. 200.","refs":[]},{"id":"01:4.2","fileNo":"01","file":"01_returns_policy.md","item":"4.2","heading":"4. Return fees","text":"No return fee is charged on a NovaCart error return.","refs":[]},{"id":"01:4.3","fileNo":"01","file":"01_returns_policy.md","item":"4.3","heading":"4. Return fees","text":"Remote areas pay a return label fee of Rs. 400 (see [file 19, Section 4]). International customers arrange and pay their own return shipping (see [file 20, Section 6]).","refs":[{"fileNo":"19","section":"4"},{"fileNo":"20","section":"6"}]},{"id":"01:5.1","fileNo":"01","file":"01_returns_policy.md","item":"5.1","heading":"5. How the refund amount is worked out","text":"The paid price of an item is its selling price minus its share of any code discount (see [file 12, Section 6]), or its share of the bundle price if it was bought in a bundle (see [file 13, Section 4]).","refs":[{"fileNo":"12","section":"6"},{"fileNo":"13","section":"4"}]},{"id":"01:5.2","fileNo":"01","file":"01_returns_policy.md","item":"5.2","heading":"5. How the refund amount is worked out","text":"The refund for each returned item is its paid price minus any restocking fee. The restocking fee is a percentage of the paid price, rounded half up.","refs":[]},{"id":"01:5.3","fileNo":"01","file":"01_returns_policy.md","item":"5.3","heading":"5. How the refund amount is worked out","text":"The refund total for a return request is the sum of the item refunds minus the one return fee from Section 4. The refund total is never below Rs. 0.","refs":[]},{"id":"01:5.4","fileNo":"01","file":"01_returns_policy.md","item":"5.4","heading":"5. How the refund amount is worked out","text":"Shipping fees and other fees paid at checkout are handled in [file 03, Section 2]. Refund method and timing are in [file 03, Section 3].","refs":[{"fileNo":"03","section":"2"},{"fileNo":"03","section":"3"}]},{"id":"01:6.1","fileNo":"01","file":"01_returns_policy.md","item":"6.1","heading":"6. Other return rules","text":"NovaCart does not offer direct exchanges. The customer returns the item and places a new order.","refs":[]},{"id":"01:6.2","fileNo":"01","file":"01_returns_policy.md","item":"6.2","heading":"6. Other return rules","text":"Returned items are inspected within 2 business days of NovaCart receiving them. The refund approval date is the day the inspection is completed.","refs":[]},{"id":"01:6.3","fileNo":"01","file":"01_returns_policy.md","item":"6.3","heading":"6. Other return rules","text":"A return request can cover some or all of the items in an order.","refs":[]},{"id":"02:1.1","fileNo":"02","file":"02_returns_policy_2025.md","item":"1.1","heading":"1. Who this policy covers","text":"This policy covers items marked \"Sold by NovaCart\".","refs":[]},{"id":"02:1.2","fileNo":"02","file":"02_returns_policy_2025.md","item":"1.2","heading":"1. Who this policy covers","text":"To return an item, the customer opens My Orders, selects \"Return item\" and submits the request inside the return window in Section 2. NovaCart approves or declines the request within 1 business day.","refs":[]},{"id":"02:1.3","fileNo":"02","file":"02_returns_policy_2025.md","item":"1.3","heading":"1. Who this policy covers","text":"An approved return must be handed to the courier within 5 days of approval. If it is not, the approval lapses and a new request is needed.","refs":[]},{"id":"02:1.4","fileNo":"02","file":"02_returns_policy_2025.md","item":"1.4","heading":"1. Who this policy covers","text":"NovaCart error means one of the following: the wrong item was delivered, the item is defective, or the item was damaged in transit. Every other return is a change-of-mind return.","refs":[]},{"id":"02:2.1","fileNo":"02","file":"02_returns_policy_2025.md","item":"2.1","heading":"2. Return windows","text":"Return windows count from the delivery date.\n\n| Category | Return window |\n| --- | --- |\n| Electronics | 10 days |\n| Clothing | 14 days |\n| Furniture/bulky | 14 days |\n| Personal care | 14 days, sealed items only |\n| Grocery/perishables | Not returnable for change of mind |","refs":[]},{"id":"02:2.2","fileNo":"02","file":"02_returns_policy_2025.md","item":"2.2","heading":"2. Return windows","text":"When the window has passed, change-of-mind returns are not accepted.","refs":[]},{"id":"02:3.1","fileNo":"02","file":"02_returns_policy_2025.md","item":"3.1","heading":"3. Condition of returned items","text":"Electronics must come back in the original packaging with all accessories. If an electronics item has been opened and is not defective, a restocking fee of 10% of the paid price applies. A sealed electronics item has no restocking fee.","refs":[]},{"id":"02:3.2","fileNo":"02","file":"02_returns_policy_2025.md","item":"3.2","heading":"3. Condition of returned items","text":"Clothing must be unworn and unwashed with the tags attached. There is no restocking fee for clothing.","refs":[]},{"id":"02:3.3","fileNo":"02","file":"02_returns_policy_2025.md","item":"3.3","heading":"3. Condition of returned items","text":"Furniture/bulky items must be unused and in the original packaging. A restocking fee of 10% of the paid price applies to non-defective furniture/bulky items.","refs":[]},{"id":"02:3.4","fileNo":"02","file":"02_returns_policy_2025.md","item":"3.4","heading":"3. Condition of returned items","text":"Personal care items must be sealed and unopened. There is no restocking fee for personal care.","refs":[]},{"id":"02:3.5","fileNo":"02","file":"02_returns_policy_2025.md","item":"3.5","heading":"3. Condition of returned items","text":"No restocking fee is charged on a NovaCart error return.","refs":[]},{"id":"02:4.1","fileNo":"02","file":"02_returns_policy_2025.md","item":"4.1","heading":"4. Return fees","text":"One return fee is charged per return request, not per item. If the request includes any furniture/bulky item, the fee is the pickup fee of Rs. 1,500. Otherwise the fee is the return label fee of Rs. 150.","refs":[]},{"id":"02:4.2","fileNo":"02","file":"02_returns_policy_2025.md","item":"4.2","heading":"4. Return fees","text":"No return fee is charged on a NovaCart error return.","refs":[]},{"id":"02:5.1","fileNo":"02","file":"02_returns_policy_2025.md","item":"5.1","heading":"5. How the refund amount is worked out","text":"The paid price of an item is the amount the customer paid for it after any discount.","refs":[]},{"id":"02:5.2","fileNo":"02","file":"02_returns_policy_2025.md","item":"5.2","heading":"5. How the refund amount is worked out","text":"The refund for each returned item is its paid price minus any restocking fee, rounded half up.","refs":[]},{"id":"02:5.3","fileNo":"02","file":"02_returns_policy_2025.md","item":"5.3","heading":"5. How the refund amount is worked out","text":"The refund total for a return request is the sum of the item refunds minus the one return fee. The refund total is never below Rs. 0.","refs":[]},{"id":"02:5.4","fileNo":"02","file":"02_returns_policy_2025.md","item":"5.4","heading":"5. How the refund amount is worked out","text":"Refunds go back to the original payment method.","refs":[]},{"id":"03:1.1","fileNo":"03","file":"03_refunds_policy.md","item":"1.1","heading":"1. Refund basics","text":"A refund is the money returned to the customer after an approved return, an approved cancellation, a lost parcel or an approved defect or damage report. How the item refund is worked out is set out in [file 01, Section 5].","refs":[{"fileNo":"01","section":"5"}]},{"id":"03:1.2","fileNo":"03","file":"03_refunds_policy.md","item":"1.2","heading":"1. Refund basics","text":"The refund approval date is the day the returned item passes inspection (see [file 01, Section 6]). For a cancellation before dispatch it is the day of the cancellation. For a lost parcel it is the day the loss is confirmed (see [file 07, Section 2]).","refs":[{"fileNo":"01","section":"6"},{"fileNo":"07","section":"2"}]},{"id":"03:2.1","fileNo":"03","file":"03_refunds_policy.md","item":"2.1","heading":"2. Which fees are refunded","text":"Standard shipping fee. It is refunded only when (a) the whole order is cancelled before dispatch, (b) every item in the order is returned because of a NovaCart error, or (c) the parcel is lost. In every other case it is not refunded, including partial returns and change-of-mind returns.","refs":[]},{"id":"03:2.2","fileNo":"03","file":"03_refunds_policy.md","item":"2.2","heading":"2. Which fees are refunded","text":"Express fee. It follows the same three conditions as the standard shipping fee. It is also refunded as store credit when express delivery is late (see [file 05, Section 2.4]).","refs":[{"fileNo":"05","section":"2.4"}]},{"id":"03:2.3","fileNo":"03","file":"03_refunds_policy.md","item":"2.3","heading":"2. Which fees are refunded","text":"Bulky surcharge. It is refunded for a bulky item when that item is returned because of a NovaCart error, when the order is cancelled before dispatch, or when the parcel is lost.","refs":[]},{"id":"03:2.4","fileNo":"03","file":"03_refunds_policy.md","item":"2.4","heading":"2. Which fees are refunded","text":"COD fee. It follows the same three conditions as the standard shipping fee.","refs":[]},{"id":"03:2.5","fileNo":"03","file":"03_refunds_policy.md","item":"2.5","heading":"2. Which fees are refunded","text":"Return label fee and pickup fee are deducted from refunds as set out in [file 01, Section 4].","refs":[{"fileNo":"01","section":"4"}]},{"id":"03:3.1","fileNo":"03","file":"03_refunds_policy.md","item":"3.1","heading":"3. Refund method and timing","text":"A refund goes back to the original payment method, except for COD orders (see 3.3).","refs":[]},{"id":"03:3.2","fileNo":"03","file":"03_refunds_policy.md","item":"3.2","heading":"3. Refund method and timing","text":"The processing time starts on the refund approval date and is counted in business days.\n\n| Original payment method | Processing time |\n| --- | --- |\n| Debit or credit card | 7 business days |\n| Online banking | 5 business days |\n| Wallet (JazzCash or Easypaisa) | 2 business days |\n| Store credit | Instant |","refs":[]},{"id":"03:3.3","fileNo":"03","file":"03_refunds_policy.md","item":"3.3","heading":"3. Refund method and timing","text":"COD orders are never refunded in cash. The customer chooses a bank transfer (5 business days) or store credit (instant).","refs":[]},{"id":"03:3.4","fileNo":"03","file":"03_refunds_policy.md","item":"3.4","heading":"3. Refund method and timing","text":"A customer can choose store credit instead of the original method and receive a bonus (see [file 14, Section 3]).","refs":[{"fileNo":"14","section":"3"}]},{"id":"03:3.5","fileNo":"03","file":"03_refunds_policy.md","item":"3.5","heading":"3. Refund method and timing","text":"Orders paid partly with store credit are refunded under [file 14, Section 6].","refs":[{"fileNo":"14","section":"6"}]},{"id":"03:3.6","fileNo":"03","file":"03_refunds_policy.md","item":"3.6","heading":"3. Refund method and timing","text":"Marketplace items have a different approval step (see [file 18, Section 2]).","refs":[{"fileNo":"18","section":"2"}]},{"id":"03:4.1","fileNo":"03","file":"03_refunds_policy.md","item":"4.1","heading":"4. Cancellations","text":"An order that has not been dispatched can be cancelled from the account. The customer receives a full refund including every fee, on the timing in 3.2 counted from the cancellation date.","refs":[]},{"id":"03:4.2","fileNo":"03","file":"03_refunds_policy.md","item":"4.2","heading":"4. Cancellations","text":"An order that has been dispatched cannot be cancelled. The customer can return it after delivery under [file 01].","refs":[{"fileNo":"01","section":null}]},{"id":"03:5.1","fileNo":"03","file":"03_refunds_policy.md","item":"5.1","heading":"5. Worked example (illustration only)","text":"Metro order, paid by card. Shirt Rs. 2,400 and trousers Rs. 3,600, both clothing, code STYLE15 applied.\n\n- Eligible subtotal: 2,400 + 3,600 = Rs. 6,000, above the Rs. 4,000 minimum.\n- Discount: 15% of 6,000 = Rs. 900, below the Rs. 1,500 cap.\n- Shares of the discount: shirt 900 x 2,400 / 6,000 = Rs. 360, trousers 900 x 3,600 / 6,000 = Rs. 540.\n- Paid prices: shirt 2,400 - 360 = Rs. 2,040, trousers 3,600 - 540 = Rs. 3,060.\n- Subtotal after discount: Rs. 5,100, at least the Metro threshold of Rs. 5,000, so standard shipping is free.\n- The customer returns the shirt for change of mind inside the window: refund = 2,040 - 200 (return label fee) = Rs. 1,840. No restocking fee applies to clothing.","refs":[]},{"id":"04:1.1","fileNo":"04","file":"04_non_returnable_items.md","item":"1.1","heading":"1. Items that cannot be returned for change of mind","text":"Grocery/perishables. Every item in this category is non-returnable for change of mind.","refs":[]},{"id":"04:1.2","fileNo":"04","file":"04_non_returnable_items.md","item":"1.2","heading":"1. Items that cannot be returned for change of mind","text":"Opened personal care items. A personal care item whose seal has been broken cannot be returned. A sealed personal care item can be returned within 14 days (see [file 01, Section 2]).","refs":[{"fileNo":"01","section":"2"}]},{"id":"04:1.3","fileNo":"04","file":"04_non_returnable_items.md","item":"1.3","heading":"1. Items that cannot be returned for change of mind","text":"Innerwear and swimwear. These clothing items cannot be returned once the hygiene seal has been removed. With the seal intact they follow the normal clothing window.","refs":[]},{"id":"04:2.1","fileNo":"04","file":"04_non_returnable_items.md","item":"2.1","heading":"2. Items that cannot be returned because of how they were sold","text":"Items marked \"Final Sale\" at the time of purchase cannot be returned for change of mind. Warranty still applies where the category has warranty (see [file 08, Section 2]).","refs":[{"fileNo":"08","section":"2"}]},{"id":"04:2.2","fileNo":"04","file":"04_non_returnable_items.md","item":"2.2","heading":"2. Items that cannot be returned because of how they were sold","text":"Furniture/bulky items marked \"Custom\" or made to order cannot be returned for change of mind.","refs":[]},{"id":"04:3.1","fileNo":"04","file":"04_non_returnable_items.md","item":"3.1","heading":"3. Exceptions","text":"Any item can be returned in any category, including the items in Sections 1 and 2, if it is a NovaCart error and it is reported inside the limits in [file 07, Section 1].","refs":[{"fileNo":"07","section":"1"}]},{"id":"04:3.2","fileNo":"04","file":"04_non_returnable_items.md","item":"3.2","heading":"3. Exceptions","text":"The return fees and restocking fees in [file 01] do not apply to returns under 3.1.","refs":[{"fileNo":"01","section":null}]},{"id":"04:4.1","fileNo":"04","file":"04_non_returnable_items.md","item":"4.1","heading":"4. Marketplace items","text":"Marketplace sellers must follow the same list of non-returnable items (see [file 18, Section 1]).","refs":[{"fileNo":"18","section":"1"}]},{"id":"05:1.1","fileNo":"05","file":"05_shipping_policy.md","item":"1.1","heading":"1. Scope and dispatch","text":"This policy covers orders Sold by NovaCart. Marketplace orders have their own dispatch rules in [file 17, Section 3].","refs":[{"fileNo":"17","section":"3"}]},{"id":"05:1.2","fileNo":"05","file":"05_shipping_policy.md","item":"1.2","heading":"1. Scope and dispatch","text":"NovaCart dispatches an order within 1 business day of payment confirmation. For COD orders the 1 business day starts when the order is verified (see [file 11, Section 3]).","refs":[{"fileNo":"11","section":"3"}]},{"id":"05:2.1","fileNo":"05","file":"05_shipping_policy.md","item":"2.1","heading":"2. Delivery times and delivery options","text":"Delivery times count in business days from dispatch.\n\n| Destination or option | Delivery time after dispatch |\n| --- | --- |\n| Metro cities, standard | 2 to 4 business days |\n| Metro cities, express | 1 to 2 business days |\n| Rest of Pakistan, standard | 4 to 6 business days |\n| Bulky items (Metro cities and Rest of Pakistan) | 5 to 8 business days |\n| Grocery (Metro cities only) | 1 to 2 business days |\n| Remote areas | see [file 19, Section 3] |\n| International | see [file 20, Section 4] |","refs":[{"fileNo":"19","section":"3"},{"fileNo":"20","section":"4"}]},{"id":"05:2.2","fileNo":"05","file":"05_shipping_policy.md","item":"2.2","heading":"2. Delivery times and delivery options","text":"Express delivery is available in Metro cities only. It cannot be chosen if the order contains a bulky item. The express fee is in [file 06, Section 2].","refs":[{"fileNo":"06","section":"2"}]},{"id":"05:2.3","fileNo":"05","file":"05_shipping_policy.md","item":"2.3","heading":"2. Delivery times and delivery options","text":"Bulky items are delivered only to Metro cities and Rest of Pakistan. Someone must be present to receive them.","refs":[]},{"id":"05:2.4","fileNo":"05","file":"05_shipping_policy.md","item":"2.4","heading":"2. Delivery times and delivery options","text":"If an express order is delivered more than 2 business days after dispatch, the express fee is refunded as store credit.","refs":[]},{"id":"05:2.5","fileNo":"05","file":"05_shipping_policy.md","item":"2.5","heading":"2. Delivery times and delivery options","text":"Grocery/perishables are delivered to Metro cities only. An order containing grocery can only be placed with a Metro city address.","refs":[]},{"id":"05:3.1","fileNo":"05","file":"05_shipping_policy.md","item":"3.1","heading":"3. Tracking and address changes","text":"A tracking number is emailed when the order is dispatched.","refs":[]},{"id":"05:3.2","fileNo":"05","file":"05_shipping_policy.md","item":"3.2","heading":"3. Tracking and address changes","text":"The delivery address can be changed only before dispatch. It cannot be changed after dispatch.","refs":[]},{"id":"05:4.1","fileNo":"05","file":"05_shipping_policy.md","item":"4.1","heading":"4. Failed deliveries","text":"The courier makes 3 delivery attempts. After the third failed attempt the order is returned to NovaCart.","refs":[]},{"id":"05:4.2","fileNo":"05","file":"05_shipping_policy.md","item":"4.2","heading":"4. Failed deliveries","text":"A prepaid order whose delivery failed is refunded for the merchandise only. Shipping, express, bulky and COD fees are kept. COD orders are cancelled (see [file 11, Section 4]).","refs":[{"fileNo":"11","section":"4"}]},{"id":"05:5.1","fileNo":"05","file":"05_shipping_policy.md","item":"5.1","heading":"5. Parcels","text":"An order may be split into several parcels that arrive on different days. No extra shipping fee is charged for split parcels.","refs":[]},{"id":"06:1.1","fileNo":"06","file":"06_shipping_fees_and_free_shipping.md","item":"1.1","heading":"1. Fee schedule","text":"The standard shipping fee depends on the destination.\n\n| Destination | Standard fee (per order) | Standard fee is free when the subtotal after discount is at least |\n| --- | --- | --- |\n| Metro cities | Rs. 250 | Rs. 5,000 |\n| Rest of Pakistan | Rs. 350 | Rs. 7,500 |\n| Remote areas | see [file 19, Section 2] | see [file 19, Section 2] |\n| International | see [file 20, Section 4] | not available |","refs":[{"fileNo":"19","section":"2"},{"fileNo":"19","section":"2"},{"fileNo":"20","section":"4"}]},{"id":"06:1.2","fileNo":"06","file":"06_shipping_fees_and_free_shipping.md","item":"1.2","heading":"1. Fee schedule","text":"The express fee is a flat Rs. 500 (Metro cities only).","refs":[]},{"id":"06:1.3","fileNo":"06","file":"06_shipping_fees_and_free_shipping.md","item":"1.3","heading":"1. Fee schedule","text":"The bulky surcharge is Rs. 1,500 per bulky item in Metro cities and Rs. 2,500 per bulky item in Rest of Pakistan.","refs":[]},{"id":"06:2.1","fileNo":"06","file":"06_shipping_fees_and_free_shipping.md","item":"2.1","heading":"2. How the fees are applied","text":"One standard shipping fee is charged per order, however many items or parcels it has.","refs":[]},{"id":"06:2.2","fileNo":"06","file":"06_shipping_fees_and_free_shipping.md","item":"2.2","heading":"2. How the fees are applied","text":"The free-shipping threshold is compared with the subtotal after discount (see [file 00, Section 5]). That subtotal is taken before shipping, express, bulky and COD charges. Items in a bundle count at their bundle price.","refs":[{"fileNo":"00","section":"5"}]},{"id":"06:2.3","fileNo":"06","file":"06_shipping_fees_and_free_shipping.md","item":"2.3","heading":"2. How the fees are applied","text":"Express replaces the standard fee. The express fee of Rs. 500 is charged in full even when the order is above the free-shipping threshold, and the FREESHIP code does not remove it.","refs":[]},{"id":"06:2.4","fileNo":"06","file":"06_shipping_fees_and_free_shipping.md","item":"2.4","heading":"2. How the fees are applied","text":"The bulky surcharge is charged for each bulky item in addition to the standard fee. It is never waived by the threshold or by FREESHIP and it does not count toward the threshold.","refs":[]},{"id":"06:2.5","fileNo":"06","file":"06_shipping_fees_and_free_shipping.md","item":"2.5","heading":"2. How the fees are applied","text":"Grocery/perishables use the standard fee, and the grocery subtotal counts toward the threshold.","refs":[]},{"id":"06:2.6","fileNo":"06","file":"06_shipping_fees_and_free_shipping.md","item":"2.6","heading":"2. How the fees are applied","text":"Which fees are refunded on returns, cancellations and lost parcels is set out in [file 03, Section 2].","refs":[{"fileNo":"03","section":"2"}]},{"id":"06:3.1","fileNo":"06","file":"06_shipping_fees_and_free_shipping.md","item":"3.1","heading":"3. Worked example (illustration only)","text":"Metro order. Headphones Rs. 3,200 (electronics) and a shirt Rs. 2,000 (clothing), code WELCOME10 applied.\n\n- Merchandise subtotal: Rs. 5,200.\n- Discount: 10% of 5,200 = Rs. 520, below the Rs. 1,000 cap.\n- Subtotal after discount: Rs. 4,680, below the Metro threshold of Rs. 5,000.\n- Standard shipping fee: Rs. 250.\n- Total payable: 4,680 + 250 = Rs. 4,930.","refs":[]},{"id":"07:1.1","fileNo":"07","file":"07_lost_or_damaged_deliveries.md","item":"1.1","heading":"1. Damaged, wrong and defective items","text":"Damaged in transit. The customer must report it within 48 hours of delivery, with photos. For grocery/perishables the limit is 24 hours.","refs":[]},{"id":"07:1.2","fileNo":"07","file":"07_lost_or_damaged_deliveries.md","item":"1.2","heading":"1. Damaged, wrong and defective items","text":"Wrong item delivered. The same limits as 1.1 apply.","refs":[]},{"id":"07:1.3","fileNo":"07","file":"07_lost_or_damaged_deliveries.md","item":"1.3","heading":"1. Damaged, wrong and defective items","text":"Defective item. The customer must report it inside the category return window (electronics 7 days, furniture/bulky 14 days, clothing 30 days, personal care 14 days, grocery/perishables 24 hours). After the window, electronics and furniture/bulky are handled under warranty (see [file 08, Section 4]).","refs":[{"fileNo":"08","section":"4"}]},{"id":"07:1.4","fileNo":"07","file":"07_lost_or_damaged_deliveries.md","item":"1.4","heading":"1. Damaged, wrong and defective items","text":"For a valid report the customer chooses a replacement or a full refund of the paid price. No restocking fee and no return fee is charged, and collection is free.","refs":[]},{"id":"07:1.5","fileNo":"07","file":"07_lost_or_damaged_deliveries.md","item":"1.5","heading":"1. Damaged, wrong and defective items","text":"Whether shipping fees are refunded is set out in [file 03, Section 2].","refs":[{"fileNo":"03","section":"2"}]},{"id":"07:2.1","fileNo":"07","file":"07_lost_or_damaged_deliveries.md","item":"2.1","heading":"2. Lost parcels","text":"A parcel is lost if it has not been delivered 10 business days after dispatch (Metro cities and Rest of Pakistan). Remote areas and International have longer limits (see [file 19, Section 3] and [file 20, Section 4]).","refs":[{"fileNo":"19","section":"3"},{"fileNo":"20","section":"4"}]},{"id":"07:2.2","fileNo":"07","file":"07_lost_or_damaged_deliveries.md","item":"2.2","heading":"2. Lost parcels","text":"For a lost parcel the customer chooses a reshipment, if the item is in stock, or a full refund including every fee (standard shipping, express, bulky and COD).","refs":[]},{"id":"07:2.3","fileNo":"07","file":"07_lost_or_damaged_deliveries.md","item":"2.3","heading":"2. Lost parcels","text":"The refund timing in [file 03, Section 3] starts on the day the loss is confirmed. No inspection step applies.","refs":[{"fileNo":"03","section":"3"}]},{"id":"07:3.1","fileNo":"07","file":"07_lost_or_damaged_deliveries.md","item":"3.1","heading":"3. Parcels marked delivered but not received","text":"The customer must report it within 3 days of the \"delivered\" status. NovaCart investigates for up to 5 business days. If the parcel is not found it is treated as lost under Section 2.","refs":[]},{"id":"08:1.1","fileNo":"08","file":"08_warranty_policy.md","item":"1.1","heading":"1. Scope","text":"This policy covers items Sold by NovaCart. Marketplace items have warranty from the seller (see [file 18, Section 4]).","refs":[{"fileNo":"18","section":"4"}]},{"id":"08:2.1","fileNo":"08","file":"08_warranty_policy.md","item":"2.1","heading":"2. Warranty periods","text":"Warranty periods count from the delivery date.\n\n| Item | Warranty period |\n| --- | --- |\n| Electronics | 12 months |\n| Chargers, cables and other accessories sold separately | 6 months |\n| Furniture/bulky | 24 months, structural defects only |\n| Clothing, personal care, grocery/perishables | No warranty |","refs":[]},{"id":"08:2.2","fileNo":"08","file":"08_warranty_policy.md","item":"2.2","heading":"2. Warranty periods","text":"An accessory that comes in the box with a device has the same warranty as the device.","refs":[]},{"id":"08:3.1","fileNo":"08","file":"08_warranty_policy.md","item":"3.1","heading":"3. What is covered","text":"Warranty covers manufacturing defects that appear during normal use.","refs":[]},{"id":"08:3.2","fileNo":"08","file":"08_warranty_policy.md","item":"3.2","heading":"3. What is covered","text":"Warranty does not cover physical damage, liquid damage, repairs by anyone other than NovaCart, normal wear, or cosmetic scratches.","refs":[]},{"id":"08:4.1","fileNo":"08","file":"08_warranty_policy.md","item":"4.1","heading":"4. Remedies","text":"NovaCart first tries to repair the item. A repair is completed within 14 calendar days of NovaCart receiving the item (see [file 09, Section 3]).","refs":[{"fileNo":"09","section":"3"}]},{"id":"08:4.2","fileNo":"08","file":"08_warranty_policy.md","item":"4.2","heading":"4. Remedies","text":"If the item cannot be repaired, NovaCart replaces it with the same or an equivalent model.","refs":[]},{"id":"08:4.3","fileNo":"08","file":"08_warranty_policy.md","item":"4.3","heading":"4. Remedies","text":"If no replacement is available, NovaCart refunds the paid price reduced by one equal part for each full month since delivery. The refund is the paid price multiplied by (W minus m) and divided by W, rounded half up, where W is the warranty period in months (12 for electronics, 6 for accessories, 24 for furniture/bulky) and m is the number of full months from the delivery date to the claim date (see [file 00, Section 1]).","refs":[{"fileNo":"00","section":"1"}]},{"id":"08:4.4","fileNo":"08","file":"08_warranty_policy.md","item":"4.4","heading":"4. Remedies","text":"A replacement item keeps the remaining warranty of the original item. It does not start a new warranty period.","refs":[]},{"id":"08:4.5","fileNo":"08","file":"08_warranty_policy.md","item":"4.5","heading":"4. Remedies","text":"An item is repaired at most 2 times. After a third defect of the same kind NovaCart replaces the item or refunds it under 4.3.","refs":[]},{"id":"08:5.1","fileNo":"08","file":"08_warranty_policy.md","item":"5.1","heading":"5. Defects inside the return window","text":"A defect reported inside the return window is a NovaCart error return and follows [file 01] and [file 07], not Section 4 of this file.","refs":[{"fileNo":"01","section":null},{"fileNo":"07","section":null}]},{"id":"08:6.1","fileNo":"08","file":"08_warranty_policy.md","item":"6.1","heading":"6. Worked example (illustration only)","text":"An electronics item with a paid price of Rs. 24,000 was delivered on 2026-01-10. The customer files a claim on 2026-04-12, and no repair or replacement is possible. Full months elapsed: 3. Refund = 24,000 x (12 - 3) / 12 = Rs. 18,000.","refs":[]},{"id":"09:1.1","fileNo":"09","file":"09_warranty_claims.md","item":"1.1","heading":"1. Making a claim","text":"The customer opens the warranty portal and submits the order number, a description of the defect and photos.","refs":[]},{"id":"09:1.2","fileNo":"09","file":"09_warranty_claims.md","item":"1.2","heading":"1. Making a claim","text":"NovaCart decides whether the claim is accepted within 3 business days of receiving the claim.","refs":[]},{"id":"09:2.1","fileNo":"09","file":"09_warranty_claims.md","item":"2.1","heading":"2. Collection and costs","text":"For an accepted claim NovaCart arranges courier collection and return of the item at no cost to the customer.","refs":[]},{"id":"09:2.2","fileNo":"09","file":"09_warranty_claims.md","item":"2.2","heading":"2. Collection and costs","text":"If the claim is rejected because the defect is not covered (see [file 08, Section 3]), the customer pays an inspection and return fee of Rs. 400 before the item is sent back.","refs":[{"fileNo":"08","section":"3"}]},{"id":"09:3.1","fileNo":"09","file":"09_warranty_claims.md","item":"3.1","heading":"3. Repair time","text":"NovaCart completes a repair within 14 calendar days of receiving the item. If it takes longer, the customer can ask for a replacement instead.","refs":[]},{"id":"09:4.1","fileNo":"09","file":"09_warranty_claims.md","item":"4.1","heading":"4. Customer responsibilities","text":"The customer is responsible for backing up and removing personal data from a device before sending it. NovaCart is not responsible for data lost during repair.","refs":[]},{"id":"09:5.1","fileNo":"09","file":"09_warranty_claims.md","item":"5.1","heading":"5. Appeals","text":"A rejected claim can be appealed within 7 days of the decision. NovaCart answers the appeal within 5 business days.","refs":[]},{"id":"10:1.1","fileNo":"10","file":"10_payments.md","item":"1.1","heading":"1. Accepted payment methods","text":"For delivery inside Pakistan NovaCart accepts debit and credit cards (Visa and Mastercard), online banking, wallets (JazzCash and Easypaisa), cash on delivery (see [file 11]) and store credit (see [file 14]).","refs":[{"fileNo":"11","section":null},{"fileNo":"14","section":null}]},{"id":"10:1.2","fileNo":"10","file":"10_payments.md","item":"1.2","heading":"1. Accepted payment methods","text":"International orders can be paid by card only (see [file 20, Section 5]).","refs":[{"fileNo":"20","section":"5"}]},{"id":"10:2.1","fileNo":"10","file":"10_payments.md","item":"2.1","heading":"2. Security","text":"Card payments above Rs. 20,000 need 3-D Secure verification.","refs":[]},{"id":"10:2.2","fileNo":"10","file":"10_payments.md","item":"2.2","heading":"2. Security","text":"NovaCart does not store full card numbers. Card details are held by the payment processor.","refs":[]},{"id":"10:3.1","fileNo":"10","file":"10_payments.md","item":"3.1","heading":"3. Order limits","text":"The maximum total payable for a card, online banking or wallet order is Rs. 250,000.","refs":[]},{"id":"10:3.2","fileNo":"10","file":"10_payments.md","item":"3.2","heading":"3. Order limits","text":"The maximum total payable for a cash on delivery order is Rs. 40,000.","refs":[]},{"id":"10:4.1","fileNo":"10","file":"10_payments.md","item":"4.1","heading":"4. When payment is taken","text":"Card, online banking and wallet payments are taken at checkout. Cash on delivery is paid to the courier at delivery.","refs":[]},{"id":"10:5.1","fileNo":"10","file":"10_payments.md","item":"5.1","heading":"5. Currency and receipts","text":"All payments are charged in PKR. If a card is issued in another currency, the card issuer sets the exchange rate and any conversion fee. NovaCart does not refund conversion fees.","refs":[]},{"id":"10:5.2","fileNo":"10","file":"10_payments.md","item":"5.2","heading":"5. Currency and receipts","text":"An email invoice is sent within 1 business day of payment confirmation.","refs":[]},{"id":"11:1.1","fileNo":"11","file":"11_cod_and_failed_payments.md","item":"1.1","heading":"1. Cash on delivery availability","text":"Cash on delivery (COD) is available for Metro cities and Rest of Pakistan. It is not available for Remote areas or International orders.","refs":[]},{"id":"11:1.2","fileNo":"11","file":"11_cod_and_failed_payments.md","item":"1.2","heading":"1. Cash on delivery availability","text":"The maximum total payable for a COD order is Rs. 50,000.","refs":[]},{"id":"11:2.1","fileNo":"11","file":"11_cod_and_failed_payments.md","item":"2.1","heading":"2. COD fee","text":"A COD fee of Rs. 100 is added to each COD order (see [file 00, Section 5]). Whether the fee is refunded is set out in [file 03, Section 2].","refs":[{"fileNo":"00","section":"5"},{"fileNo":"03","section":"2"}]},{"id":"11:3.1","fileNo":"11","file":"11_cod_and_failed_payments.md","item":"3.1","heading":"3. COD verification","text":"A COD order with a total payable above Rs. 20,000 is verified by phone. If the customer does not confirm within 24 hours of placing the order, the order is cancelled.","refs":[]},{"id":"11:4.1","fileNo":"11","file":"11_cod_and_failed_payments.md","item":"4.1","heading":"4. Refused or failed COD deliveries","text":"If delivery fails 3 times, or the customer refuses the parcel, the COD order is cancelled.","refs":[]},{"id":"11:4.2","fileNo":"11","file":"11_cod_and_failed_payments.md","item":"4.2","heading":"4. Refused or failed COD deliveries","text":"A second failed or refused COD delivery within 12 months limits the account to prepaid payment methods for 90 days.","refs":[]},{"id":"11:5.1","fileNo":"11","file":"11_cod_and_failed_payments.md","item":"5.1","heading":"5. Failed online payments","text":"An order with a failed online payment is held for 24 hours and then cancelled automatically.","refs":[]},{"id":"11:5.2","fileNo":"11","file":"11_cod_and_failed_payments.md","item":"5.2","heading":"5. Failed online payments","text":"If money was taken but no order was confirmed, or a customer was charged twice, the amount is reversed in the same number of business days as the refund times in [file 03, Section 3]: 7 for cards, 5 for online banking and 2 for wallets.","refs":[{"fileNo":"03","section":"3"}]},{"id":"11:6.1","fileNo":"11","file":"11_cod_and_failed_payments.md","item":"6.1","heading":"6. COD refunds","text":"COD refunds follow [file 03, Section 3].","refs":[{"fileNo":"03","section":"3"}]},{"id":"12:1.1","fileNo":"12","file":"12_promo_code_rules.md","item":"1.1","heading":"1. General rules","text":"A code is entered at checkout. It cannot be added to an order after the order is placed.","refs":[]},{"id":"12:1.2","fileNo":"12","file":"12_promo_code_rules.md","item":"1.2","heading":"1. General rules","text":"Only one discount code can be used per order. FREESHIP is a shipping code, not a discount code, so it can be used together with one discount code.","refs":[]},{"id":"12:1.3","fileNo":"12","file":"12_promo_code_rules.md","item":"1.3","heading":"1. General rules","text":"A code is valid if the order was placed on or before the code's last order date (inclusive) and the order meets the code's conditions.","refs":[]},{"id":"12:1.4","fileNo":"12","file":"12_promo_code_rules.md","item":"1.4","heading":"1. General rules","text":"Codes can be used on items that are on sale. The discount is calculated on the sale price.","refs":[]},{"id":"12:1.5","fileNo":"12","file":"12_promo_code_rules.md","item":"1.5","heading":"1. General rules","text":"A discount code applies to every item in the order that meets the code's category condition, including items that are part of a bundle deal.","refs":[]},{"id":"12:1.6","fileNo":"12","file":"12_promo_code_rules.md","item":"1.6","heading":"1. General rules","text":"A code is used up when the order is placed. It is not given back, except when the whole order is cancelled before dispatch, when the code is restored.","refs":[]},{"id":"12:2.1","fileNo":"12","file":"12_promo_code_rules.md","item":"2.1","heading":"2. Codes","text":"The codes below are the only codes in force.\n\n| Code | Benefit | Eligible items | Minimum eligible subtotal | Maximum discount | Last order date |\n| --- | --- | --- | --- | --- | --- |\n| WELCOME10 | 10% off | All categories except grocery/perishables | Rs. 3,000 | Rs. 1,000 | 2026-12-31 |\n| STYLE15 | 15% off | Clothing only | Rs. 4,000 | Rs. 1,500 | 2026-08-31 |\n| TECH500 | Rs. 500 off | Electronics only | Rs. 15,000 | Rs. 500 | 2027-01-31 |\n| FREESHIP | Removes the standard shipping fee | Whole order | Rs. 2,000 | Not applicable | 2026-12-31 |","refs":[]},{"id":"12:2.2","fileNo":"12","file":"12_promo_code_rules.md","item":"2.2","heading":"2. Codes","text":"WELCOME10 can be used on a customer's first order only.","refs":[]},{"id":"12:2.3","fileNo":"12","file":"12_promo_code_rules.md","item":"2.3","heading":"2. Codes","text":"TECH500 can be used once per customer per calendar month.","refs":[]},{"id":"12:3.1","fileNo":"12","file":"12_promo_code_rules.md","item":"3.1","heading":"3. Eligible subtotal and discount","text":"The eligible subtotal is the sum of the selling prices (after any sale price) of the items that are eligible for the code.","refs":[]},{"id":"12:3.2","fileNo":"12","file":"12_promo_code_rules.md","item":"3.2","heading":"3. Eligible subtotal and discount","text":"For a percentage code the discount is the eligible subtotal multiplied by the rate, rounded half up, and then limited to the maximum discount.","refs":[]},{"id":"12:3.3","fileNo":"12","file":"12_promo_code_rules.md","item":"3.3","heading":"3. Eligible subtotal and discount","text":"For TECH500 the discount is Rs. 500. A discount is never more than the eligible subtotal.","refs":[]},{"id":"12:3.4","fileNo":"12","file":"12_promo_code_rules.md","item":"3.4","heading":"3. Eligible subtotal and discount","text":"The minimum is checked against the eligible subtotal at checkout, before the discount. A later return does not remove the discount from the remaining items.","refs":[]},{"id":"12:4.1","fileNo":"12","file":"12_promo_code_rules.md","item":"4.1","heading":"4. Exclusions","text":"Codes do not apply to items sold by marketplace sellers.","refs":[]},{"id":"12:4.2","fileNo":"12","file":"12_promo_code_rules.md","item":"4.2","heading":"4. Exclusions","text":"Codes do not apply to items marked \"Final Sale\".","refs":[]},{"id":"12:4.3","fileNo":"12","file":"12_promo_code_rules.md","item":"4.3","heading":"4. Exclusions","text":"WELCOME10 does not apply to grocery/perishables.","refs":[]},{"id":"12:5.1","fileNo":"12","file":"12_promo_code_rules.md","item":"5.1","heading":"5. The FREESHIP code","text":"FREESHIP removes the standard shipping fee. It does not remove the express fee, the bulky surcharge or the COD fee.","refs":[]},{"id":"12:5.2","fileNo":"12","file":"12_promo_code_rules.md","item":"5.2","heading":"5. The FREESHIP code","text":"FREESHIP is valid for orders to Metro cities and Rest of Pakistan only. It is not valid for Remote areas or International orders.","refs":[]},{"id":"12:5.3","fileNo":"12","file":"12_promo_code_rules.md","item":"5.3","heading":"5. The FREESHIP code","text":"The minimum Rs. 2,000 is checked against the merchandise subtotal after any other discount code.","refs":[]},{"id":"12:6.1","fileNo":"12","file":"12_promo_code_rules.md","item":"6.1","heading":"6. Splitting a code discount across items","text":"To work out a refund for one item, the discount is split across the eligible items in proportion to their selling prices. Each item's share is the discount multiplied by the item's price and divided by the eligible subtotal, rounded half up.","refs":[]},{"id":"12:6.2","fileNo":"12","file":"12_promo_code_rules.md","item":"6.2","heading":"6. Splitting a code discount across items","text":"If the rounded shares do not add up to the discount, the difference is added to or taken from the most expensive eligible item. If two items have the same price, the one listed first in the order is used.","refs":[]},{"id":"12:6.3","fileNo":"12","file":"12_promo_code_rules.md","item":"6.3","heading":"6. Splitting a code discount across items","text":"The paid price of an item is its selling price minus its share of the discount (see [file 01, Section 5]).","refs":[{"fileNo":"01","section":"5"}]},{"id":"12:6.4","fileNo":"12","file":"12_promo_code_rules.md","item":"6.4","heading":"6. Splitting a code discount across items","text":"Worked example (illustration only). TECH500 is used on three electronics items priced Rs. 5,000, Rs. 5,000 and Rs. 5,500. The eligible subtotal is Rs. 15,500, above the Rs. 15,000 minimum. The shares are 161, 161 and 177, which add up to 499. The missing rupee goes to the Rs. 5,500 item, so the shares are 161, 161 and 178.","refs":[]},{"id":"13:1.1","fileNo":"13","file":"13_sales_and_bundles.md","item":"1.1","heading":"1. Sale prices","text":"A sale price already includes the reduction. The sale price is the item's selling price at checkout and in refunds.","refs":[]},{"id":"13:1.2","fileNo":"13","file":"13_sales_and_bundles.md","item":"1.2","heading":"1. Sale prices","text":"A sale price counts as the item price in step 1 of [file 00, Section 5].","refs":[{"fileNo":"00","section":"5"}]},{"id":"13:2.1","fileNo":"13","file":"13_sales_and_bundles.md","item":"2.1","heading":"2. Flash sales and Final Sale","text":"A flash sale lasts up to 24 hours. Each customer can buy at most 2 units of a flash sale item.","refs":[]},{"id":"13:2.2","fileNo":"13","file":"13_sales_and_bundles.md","item":"2.2","heading":"2. Flash sales and Final Sale","text":"Flash sale items can be returned under the normal rules unless they are marked \"Final Sale\".","refs":[]},{"id":"13:2.3","fileNo":"13","file":"13_sales_and_bundles.md","item":"2.3","heading":"2. Flash sales and Final Sale","text":"Items marked \"Final Sale\" cannot be returned for change of mind (see [file 04, Section 2]). Warranty still applies where the category has warranty.","refs":[{"fileNo":"04","section":"2"}]},{"id":"13:3.1","fileNo":"13","file":"13_sales_and_bundles.md","item":"3.1","heading":"3. Price changes","text":"If an item's price drops after the customer has bought it, NovaCart does not refund the difference.","refs":[]},{"id":"13:4.1","fileNo":"13","file":"13_sales_and_bundles.md","item":"4.1","heading":"4. Bundle deals","text":"A bundle deal is a set of items sold together for one bundle price. Each item in the bundle has a list price shown on the bundle page.","refs":[]},{"id":"13:4.2","fileNo":"13","file":"13_sales_and_bundles.md","item":"4.2","heading":"4. Bundle deals","text":"Bundle deals cannot be combined with discount codes. Items in a bundle are not eligible for any discount code and do not count toward an eligible subtotal.","refs":[]},{"id":"13:4.3","fileNo":"13","file":"13_sales_and_bundles.md","item":"4.3","heading":"4. Bundle deals","text":"The bundle price counts toward the merchandise subtotal and toward free-shipping thresholds.","refs":[]},{"id":"13:4.4","fileNo":"13","file":"13_sales_and_bundles.md","item":"4.4","heading":"4. Bundle deals","text":"If one item of a bundle is returned, its share of the bundle price is the bundle price multiplied by the item's list price and divided by the sum of the list prices of all items in the bundle, rounded half up. If the shares do not add up to the bundle price, the difference goes to the item with the highest list price (the first listed if two are equal).","refs":[]},{"id":"13:4.5","fileNo":"13","file":"13_sales_and_bundles.md","item":"4.5","heading":"4. Bundle deals","text":"If every item of a bundle is returned, the refund is the full bundle price, before any fees.","refs":[]},{"id":"13:4.6","fileNo":"13","file":"13_sales_and_bundles.md","item":"4.6","heading":"4. Bundle deals","text":"Each item in a bundle follows the return window and the condition rules of its own category.","refs":[]},{"id":"13:4.7","fileNo":"13","file":"13_sales_and_bundles.md","item":"4.7","heading":"4. Bundle deals","text":"Worked example (illustration only). A starter bundle costs Rs. 3,333 and contains earphones (list price Rs. 2,500), a charger (list price Rs. 1,000) and a cable (list price Rs. 500). The list prices add up to Rs. 4,000. The shares are earphones 2,083, charger 833 and cable 417, which add up to 3,333.","refs":[]},{"id":"14:1.1","fileNo":"14","file":"14_store_credit.md","item":"1.1","heading":"1. What store credit is","text":"Store credit is a balance held on the customer's NovaCart account. Rs. 1 of credit is worth Rs. 1.","refs":[]},{"id":"14:2.1","fileNo":"14","file":"14_store_credit.md","item":"2.1","heading":"2. How credit is issued","text":"Credit is issued when a customer chooses store credit for a refund, when NovaCart refunds a late express fee (see [file 05, Section 2.4]) and when NovaCart gives goodwill credit.","refs":[{"fileNo":"05","section":"2.4"}]},{"id":"14:3.1","fileNo":"14","file":"14_store_credit.md","item":"3.1","heading":"3. Store credit bonus","text":"A customer who chooses store credit instead of a refund to the original payment method receives a bonus of 5% of the refund amount, rounded half up, up to a maximum of Rs. 1,000 per refund.","refs":[]},{"id":"14:3.2","fileNo":"14","file":"14_store_credit.md","item":"3.2","heading":"3. Store credit bonus","text":"There is no bonus on credit that can only be issued as store credit, such as a late express fee refund or the part of an order that was paid with store credit.","refs":[]},{"id":"14:3.3","fileNo":"14","file":"14_store_credit.md","item":"3.3","heading":"3. Store credit bonus","text":"The bonus expires together with the credit it was issued with.","refs":[]},{"id":"14:4.1","fileNo":"14","file":"14_store_credit.md","item":"4.1","heading":"4. Expiry","text":"Credit expires 12 months after the day it is issued, on the same calendar date. Unused credit is lost on expiry and the expiry date cannot be extended.","refs":[]},{"id":"14:5.1","fileNo":"14","file":"14_store_credit.md","item":"5.1","heading":"5. Using store credit","text":"Credit can be used at checkout for all or part of an order, together with other payment methods.","refs":[]},{"id":"14:5.2","fileNo":"14","file":"14_store_credit.md","item":"5.2","heading":"5. Using store credit","text":"Credit cannot be used to buy items from marketplace sellers (see [file 17, Section 6]).","refs":[{"fileNo":"17","section":"6"}]},{"id":"14:5.3","fileNo":"14","file":"14_store_credit.md","item":"5.3","heading":"5. Using store credit","text":"Credit cannot be withdrawn as cash and cannot be transferred to another account.","refs":[]},{"id":"14:6.1","fileNo":"14","file":"14_store_credit.md","item":"6.1","heading":"6. Orders paid partly with store credit","text":"A refund for an order paid partly with store credit goes first to the other payment method, up to the amount that method paid. Any remainder is refunded to store credit.","refs":[]},{"id":"14:6.2","fileNo":"14","file":"14_store_credit.md","item":"6.2","heading":"6. Orders paid partly with store credit","text":"Worked example (illustration only). A customer chooses store credit for a refund of Rs. 8,000. The bonus is 5% of 8,000 = Rs. 400, so Rs. 8,400 of credit is issued.","refs":[]},{"id":"15:1.1","fileNo":"15","file":"15_privacy_policy.md","item":"1.1","heading":"1. Who can have an account","text":"NovaCart accounts are for people aged 18 or over.","refs":[]},{"id":"15:2.1","fileNo":"15","file":"15_privacy_policy.md","item":"2.1","heading":"2. Data NovaCart collects","text":"NovaCart collects account details (name, email, phone number, delivery addresses), order history, payment tokens issued by the payment processor, and technical data such as device type and IP address.","refs":[]},{"id":"15:3.1","fileNo":"15","file":"15_privacy_policy.md","item":"3.1","heading":"3. How data is used","text":"Data is used to process orders, deliver parcels, handle returns and warranty claims, prevent fraud and improve the service.","refs":[]},{"id":"15:3.2","fileNo":"15","file":"15_privacy_policy.md","item":"3.2","heading":"3. How data is used","text":"Marketing emails are sent only to customers who have agreed to them. A customer can opt out at any time (see [file 16, Section 5]).","refs":[{"fileNo":"16","section":"5"}]},{"id":"15:4.1","fileNo":"15","file":"15_privacy_policy.md","item":"4.1","heading":"4. Sharing data","text":"NovaCart shares delivery details with couriers and payment details with payment processors.","refs":[]},{"id":"15:4.2","fileNo":"15","file":"15_privacy_policy.md","item":"4.2","heading":"4. Sharing data","text":"For marketplace orders NovaCart shares the customer's name, delivery address and phone number with the seller. No other personal data is shared with sellers.","refs":[]},{"id":"15:4.3","fileNo":"15","file":"15_privacy_policy.md","item":"4.3","heading":"4. Sharing data","text":"NovaCart does not sell personal data.","refs":[]},{"id":"15:5.1","fileNo":"15","file":"15_privacy_policy.md","item":"5.1","heading":"5. Cookies","text":"Essential cookies are always on. Analytics cookies are optional and the customer can switch them off in the cookie settings.","refs":[]},{"id":"15:6.1","fileNo":"15","file":"15_privacy_policy.md","item":"6.1","heading":"6. Security","text":"An account is locked for 30 minutes after 5 failed login attempts.","refs":[]},{"id":"15:6.2","fileNo":"15","file":"15_privacy_policy.md","item":"6.2","heading":"6. Security","text":"NovaCart tells affected customers about a data breach within 72 hours of confirming it.","refs":[]},{"id":"15:7.1","fileNo":"15","file":"15_privacy_policy.md","item":"7.1","heading":"7. Contact","text":"Privacy questions go to privacy@novacart.example.","refs":[]},{"id":"16:1.1","fileNo":"16","file":"16_data_requests_and_retention.md","item":"1.1","heading":"1. Asking for a copy of your data","text":"A customer can ask for a copy of their personal data. NovaCart answers within 30 calendar days.","refs":[]},{"id":"16:1.2","fileNo":"16","file":"16_data_requests_and_retention.md","item":"1.2","heading":"1. Asking for a copy of your data","text":"The first request in any 12-month period is free. Each further request in the same period costs Rs. 500.","refs":[]},{"id":"16:1.3","fileNo":"16","file":"16_data_requests_and_retention.md","item":"1.3","heading":"1. Asking for a copy of your data","text":"NovaCart verifies the customer's identity before sharing data.","refs":[]},{"id":"16:2.1","fileNo":"16","file":"16_data_requests_and_retention.md","item":"2.1","heading":"2. Deleting data","text":"A customer can ask for their account and personal data to be deleted. NovaCart completes the deletion within 30 calendar days.","refs":[]},{"id":"16:2.2","fileNo":"16","file":"16_data_requests_and_retention.md","item":"2.2","heading":"2. Deleting data","text":"NovaCart cannot delete data for an order that is still inside its return window or warranty period, or data it must keep by law, until that period ends.","refs":[]},{"id":"16:3.1","fileNo":"16","file":"16_data_requests_and_retention.md","item":"3.1","heading":"3. How long data is kept","text":"Retention periods are listed below.\n\n| Data | Retention |\n| --- | --- |\n| Order and invoice records | 6 years |\n| Account data | Deleted or anonymised 12 months after the last activity |\n| Customer support chat records | 24 months |\n| Full card numbers | Never stored by NovaCart |","refs":[]},{"id":"16:4.1","fileNo":"16","file":"16_data_requests_and_retention.md","item":"4.1","heading":"4. Corrections","text":"NovaCart corrects wrong personal data within 7 days of a request.","refs":[]},{"id":"16:5.1","fileNo":"16","file":"16_data_requests_and_retention.md","item":"5.1","heading":"5. Marketing preferences","text":"An unsubscribe request takes effect within 3 business days.","refs":[]},{"id":"17:1.1","fileNo":"17","file":"17_seller_marketplace_rules.md","item":"1.1","heading":"1. Who can sell","text":"A seller must be a registered business with a CNIC or NTN and a bank account in the business name. Marketplace items are shown as \"Sold by\" followed by the seller's name.","refs":[]},{"id":"17:2.1","fileNo":"17","file":"17_seller_marketplace_rules.md","item":"2.1","heading":"2. Commission and payout","text":"NovaCart charges a commission on the selling price of each item, by category.\n\n| Category | Commission |\n| --- | --- |\n| Electronics | 6% |\n| Clothing | 12% |\n| Furniture/bulky | 10% |\n| Personal care | 10% |\n| Grocery/perishables | 5% |","refs":[]},{"id":"17:2.2","fileNo":"17","file":"17_seller_marketplace_rules.md","item":"2.2","heading":"2. Commission and payout","text":"NovaCart also charges a handling fee of Rs. 50 per order item line.","refs":[]},{"id":"17:2.3","fileNo":"17","file":"17_seller_marketplace_rules.md","item":"2.3","heading":"2. Commission and payout","text":"The seller payout for an item is the selling price minus the commission (rounded half up) minus the handling fee. Example: a clothing item sold for Rs. 3,000 has a commission of Rs. 360 and a payout of 3,000 - 360 - 50 = Rs. 2,590.","refs":[]},{"id":"17:2.4","fileNo":"17","file":"17_seller_marketplace_rules.md","item":"2.4","heading":"2. Commission and payout","text":"Payouts are made every Wednesday for items delivered at least 7 days earlier that are not in a return or dispute.","refs":[]},{"id":"17:3.1","fileNo":"17","file":"17_seller_marketplace_rules.md","item":"3.1","heading":"3. Dispatch","text":"A seller must dispatch an order within 2 business days of payment confirmation.","refs":[]},{"id":"17:4.1","fileNo":"17","file":"17_seller_marketplace_rules.md","item":"4.1","heading":"4. Seller performance","text":"A seller whose cancellation rate is above 5% in a rolling 30 days gets a warning. Above 10% the seller is suspended for 30 days.","refs":[]},{"id":"17:5.1","fileNo":"17","file":"17_seller_marketplace_rules.md","item":"5.1","heading":"5. Prohibited items","text":"Sellers must not list counterfeit goods, items that are illegal to sell in Pakistan, or items that NovaCart has banned.","refs":[]},{"id":"17:6.1","fileNo":"17","file":"17_seller_marketplace_rules.md","item":"6.1","heading":"6. Rules that affect customers","text":"Marketplace items follow the return windows of [file 01] and the extra rules in [file 18].","refs":[{"fileNo":"01","section":null},{"fileNo":"18","section":null}]},{"id":"17:6.2","fileNo":"17","file":"17_seller_marketplace_rules.md","item":"6.2","heading":"6. Rules that affect customers","text":"Store credit cannot be used for marketplace items, and promo codes do not apply to them.","refs":[]},{"id":"18:1.1","fileNo":"18","file":"18_seller_return_obligations.md","item":"1.1","heading":"1. Return windows and conditions","text":"Marketplace items follow the return windows, conditions and fees in [file 01], and the list of non-returnable items in [file 04]. A seller cannot set a shorter window or add fees.","refs":[{"fileNo":"01","section":null},{"fileNo":"04","section":null}]},{"id":"18:2.1","fileNo":"18","file":"18_seller_return_obligations.md","item":"2.1","heading":"2. Confirming a return","text":"The seller must confirm receipt of a returned item within 3 business days of NovaCart's courier delivering it to the seller. For marketplace items this replaces the 2-business-day inspection in [file 01, Section 6]. If the seller does not confirm in time, NovaCart approves the refund on the third business day.","refs":[{"fileNo":"01","section":"6"}]},{"id":"18:2.2","fileNo":"18","file":"18_seller_return_obligations.md","item":"2.2","heading":"2. Confirming a return","text":"The refund approval date is the day the seller confirms, or the third business day if the seller does not confirm.","refs":[]},{"id":"18:3.1","fileNo":"18","file":"18_seller_return_obligations.md","item":"3.1","heading":"3. Who pays for the return","text":"The seller pays the return shipping for a NovaCart error return. The customer pays the return label fee for a change-of-mind return, as set out in [file 01, Section 4].","refs":[{"fileNo":"01","section":"4"}]},{"id":"18:4.1","fileNo":"18","file":"18_seller_return_obligations.md","item":"4.1","heading":"4. Warranty on marketplace items","text":"The seller gives the warranty on marketplace items. For electronics the seller's warranty is at least 6 months from delivery. The NovaCart warranty in [file 08] does not apply.","refs":[{"fileNo":"08","section":null}]},{"id":"18:5.1","fileNo":"18","file":"18_seller_return_obligations.md","item":"5.1","heading":"5. Refused returns","text":"If a seller refuses a valid return, NovaCart refunds the customer and charges the seller a penalty of Rs. 1,000 for each refused return.","refs":[]},{"id":"18:6.1","fileNo":"18","file":"18_seller_return_obligations.md","item":"6.1","heading":"6. Disputes","text":"NovaCart decides a dispute between a customer and a seller within 5 business days.","refs":[]},{"id":"19:1.1","fileNo":"19","file":"19_remote_areas_addendum.md","item":"1.1","heading":"1. Scope","text":"This addendum applies to deliveries to Remote areas: Azad Jammu & Kashmir and Gilgit-Baltistan (see [file 00, Section 2]). Where this addendum is silent, the general files apply.","refs":[{"fileNo":"00","section":"2"}]},{"id":"19:2.1","fileNo":"19","file":"19_remote_areas_addendum.md","item":"2.1","heading":"2. Shipping fees","text":"The standard shipping fee is Rs. 600 per order. It is free when the subtotal after discount is at least Rs. 12,000.","refs":[]},{"id":"19:2.2","fileNo":"19","file":"19_remote_areas_addendum.md","item":"2.2","heading":"2. Shipping fees","text":"Express delivery, bulky items and grocery/perishables are not available for Remote areas. Cash on delivery is not available for Remote areas.","refs":[]},{"id":"19:2.3","fileNo":"19","file":"19_remote_areas_addendum.md","item":"2.3","heading":"2. Shipping fees","text":"The FREESHIP code is not valid for Remote areas.","refs":[]},{"id":"19:3.1","fileNo":"19","file":"19_remote_areas_addendum.md","item":"3.1","heading":"3. Delivery times","text":"Delivery takes 7 to 10 business days after dispatch.","refs":[]},{"id":"19:3.2","fileNo":"19","file":"19_remote_areas_addendum.md","item":"3.2","heading":"3. Delivery times","text":"A parcel is lost if it has not been delivered 15 business days after dispatch (see [file 07, Section 2]).","refs":[{"fileNo":"07","section":"2"}]},{"id":"19:4.1","fileNo":"19","file":"19_remote_areas_addendum.md","item":"4.1","heading":"4. Returns","text":"Return windows in Remote areas are 3 days longer than the windows in [file 01, Section 2]: electronics 10 days, clothing 33 days, personal care 17 days (sealed items only).","refs":[{"fileNo":"01","section":"2"}]},{"id":"19:4.2","fileNo":"19","file":"19_remote_areas_addendum.md","item":"4.2","heading":"4. Returns","text":"The return label fee is Rs. 400. All other return rules follow [file 01].","refs":[{"fileNo":"01","section":null}]},{"id":"19:5.1","fileNo":"19","file":"19_remote_areas_addendum.md","item":"5.1","heading":"5. Warranty","text":"A warranty repair in Remote areas is completed within 21 calendar days of NovaCart receiving the item, instead of 14.","refs":[]},{"id":"20:1.1","fileNo":"20","file":"20_international_addendum.md","item":"1.1","heading":"1. Scope","text":"This addendum applies to deliveries to the USA, the UK and the UAE (see [file 00, Section 2]). Where this addendum is silent, the general files apply.","refs":[{"fileNo":"00","section":"2"}]},{"id":"20:2.1","fileNo":"20","file":"20_international_addendum.md","item":"2.1","heading":"2. What can be ordered","text":"Electronics, clothing and personal care can be delivered internationally. Grocery/perishables and furniture/bulky items cannot.","refs":[]},{"id":"20:3.1","fileNo":"20","file":"20_international_addendum.md","item":"3.1","heading":"3. Prices and GST","text":"GST is not charged on international orders. The price payable for each item is its listed price divided by 1.18, rounded half up to a whole rupee per item.","refs":[]},{"id":"20:3.2","fileNo":"20","file":"20_international_addendum.md","item":"3.2","heading":"3. Prices and GST","text":"Discount codes and their minimum amounts are worked out on these export prices.","refs":[]},{"id":"20:4.1","fileNo":"20","file":"20_international_addendum.md","item":"4.1","heading":"4. Shipping","text":"Shipping is a flat fee per order.\n\n| Destination | Shipping fee | Delivery time after dispatch |\n| --- | --- | --- |\n| UAE | Rs. 3,500 | 7 to 10 business days |\n| UK | Rs. 5,500 | 10 to 14 business days |\n| USA | Rs. 6,500 | 12 to 18 business days |","refs":[]},{"id":"20:4.2","fileNo":"20","file":"20_international_addendum.md","item":"4.2","heading":"4. Shipping","text":"There is no free-shipping threshold, no express delivery and no FREESHIP code for international orders.","refs":[]},{"id":"20:4.3","fileNo":"20","file":"20_international_addendum.md","item":"4.3","heading":"4. Shipping","text":"A parcel is lost if it has not been delivered 25 business days after dispatch (see [file 07, Section 2]).","refs":[{"fileNo":"07","section":"2"}]},{"id":"20:4.4","fileNo":"20","file":"20_international_addendum.md","item":"4.4","heading":"4. Shipping","text":"Worked example (illustration only). A UAE order has one electronics item with a listed price of Rs. 11,800 and uses WELCOME10. Export price: 11,800 / 1.18 = Rs. 10,000. The discount is 10% of 10,000 = Rs. 1,000, which equals the cap. Subtotal after discount: Rs. 9,000. Shipping: Rs. 3,500. Total payable: Rs. 12,500.","refs":[]},{"id":"20:5.1","fileNo":"20","file":"20_international_addendum.md","item":"5.1","heading":"5. Payment","text":"International orders are paid by card only. The customer pays any customs duties and import taxes in the destination country.","refs":[]},{"id":"20:6.1","fileNo":"20","file":"20_international_addendum.md","item":"6.1","heading":"6. Returns","text":"The return window is 10 days from delivery for every category that can be shipped internationally.","refs":[]},{"id":"20:6.2","fileNo":"20","file":"20_international_addendum.md","item":"6.2","heading":"6. Returns","text":"Personal care items cannot be returned from international orders for change of mind. They can be returned for a NovaCart error.","refs":[]},{"id":"20:6.3","fileNo":"20","file":"20_international_addendum.md","item":"6.3","heading":"6. Returns","text":"The customer arranges and pays the return shipping. No return label fee is charged. Restocking fees in [file 01, Section 3] still apply.","refs":[{"fileNo":"01","section":"3"}]},{"id":"20:6.4","fileNo":"20","file":"20_international_addendum.md","item":"6.4","heading":"6. Returns","text":"Refunds go back to the card 10 business days after the refund approval date, instead of the time in [file 03, Section 3]. Shipping fees are refunded only under [file 03, Section 2].","refs":[{"fileNo":"03","section":"3"},{"fileNo":"03","section":"2"}]},{"id":"20:7.1","fileNo":"20","file":"20_international_addendum.md","item":"7.1","heading":"7. Warranty","text":"Electronics keep the 12-month warranty in [file 08]. The customer pays shipping to NovaCart and NovaCart pays the return shipping.","refs":[{"fileNo":"08","section":null}]},{"id":"21:1.1","fileNo":"21","file":"21_shipping_fee_update_2027.md","item":"1.1","heading":"1. What changes","text":"From 2027-02-01 the shipping fees for Metro cities and Rest of Pakistan are as follows.\n\n| Destination | Standard fee (per order) | Standard fee is free when the subtotal after discount is at least |\n| --- | --- | --- |\n| Metro cities | Rs. 300 | Rs. 6,000 |\n| Rest of Pakistan | Rs. 400 | Rs. 8,500 |","refs":[]},{"id":"21:1.2","fileNo":"21","file":"21_shipping_fee_update_2027.md","item":"1.2","heading":"1. What changes","text":"The express fee becomes Rs. 600 (Metro cities only).","refs":[]},{"id":"21:1.3","fileNo":"21","file":"21_shipping_fee_update_2027.md","item":"1.3","heading":"1. What changes","text":"The bulky surcharge becomes Rs. 1,800 per bulky item in Metro cities and Rs. 3,000 per bulky item in Rest of Pakistan.","refs":[]},{"id":"21:2.1","fileNo":"21","file":"21_shipping_fee_update_2027.md","item":"2.1","heading":"2. What does not change","text":"Fees for Remote areas and International orders are unchanged and stay in [file 19] and [file 20]. All other shipping rules stay as in [file 05] and [file 06].","refs":[{"fileNo":"19","section":null},{"fileNo":"20","section":null},{"fileNo":"05","section":null},{"fileNo":"06","section":null}]}]};
